 AppUpdater updater=new AppUpdater(this); WebView web; final ExecutorService worker=Executors.newSingleThreadExecutor();
 int pendingId; String pendingMethod; JSONObject pendingArgs; ArrayList<String> trashDone; ArrayList<Uri> trashBatch; ArrayList<Uri> trashRemaining; int trashVerificationFailed=0;
