 final String origin="https://app.local/";
 Uri uri(String id){if(!id.matches("[iv]_[0-9]+"))throw new IllegalArgumentException("无效媒体编号");return ContentUris.withAppendedId(id.startsWith("v_")?MediaStore.Video.Media.EXTERNAL_CONTENT_URI:MediaStore.Images.Media.EXTERNAL_CONTENT_URI,Long.parseLong(id.substring(2)));}
