 WebResourceResponse resource(WebResourceRequest request){try{Uri u=request.getUrl();if(u.getHost().equals("app.local")){String p=u.getPath().substring(1);if(!Arrays.asList("index.html","style.css","app.js","model.js","management.js","library.js","viewer.js","extras.js").contains(p))return missing();String mime=p.endsWith("css")?"text/css":p.endsWith("js")?"application/javascript":"text/html";return new WebResourceResponse(mime,"UTF-8",getAssets().open("web/"+p));}if(!u.getHost().equals("media.local"))return missing();String mid=u.getPath().substring(1);Uri media=uri(mid);if("1".equals(u.getQueryParameter("thumb"))){File cached=new File(getCacheDir(),mid+".jpg");if(!cached.exists()){Bitmap b=getContentResolver().loadThumbnail(media,new Size(480,480),null);try(FileOutputStream out=new FileOutputStream(cached)){b.compress(Bitmap.CompressFormat.JPEG,85,out);}b.recycle();}return new WebResourceResponse("image/jpeg",null,new FileInputStream(cached));}String mime=getContentResolver().getType(media);long size=0;try(Cursor c=getContentResolver().query(media,new String[]{"_size"},null,null,null)){if(c!=null&&c.moveToFirst())size=c.getLong(0);}InputStream stream=getContentResolver().openInputStream(media);Map<String,String> headers=new HashMap<>();headers.put("Access-Control-Allow-Origin",origin.substring(0,origin.length()-1));headers.put("Accept-Ranges","bytes");String range=request.getRequestHeaders().get("Range");if(range!=null&&range.matches("bytes=[0-9]+-.*")&&size>0){long start=Long.parseLong(range.substring(6).split("-",-1)[0]);if(start>=size){stream.close();return missing();}long left=start;while(left>0){long skipped=stream.skip(left);if(skipped<=0)break;left-=skipped;}headers.put("Content-Range","bytes "+start+"-"+(size-1)+"/"+size);headers.put("Content-Length",String.valueOf(size-start));return new WebResourceResponse(mime,null,206,"Partial Content",headers,stream);}if(size>0)headers.put("Content-Length",String.valueOf(size));return new WebResourceResponse(mime,null,200,"OK",headers,stream);}catch(Exception e){return missing();}}
