 class Bridge {@JavascriptInterface public void call(int callId,String method,String json){worker.execute(()->{try{dispatch(callId,method,new JSONObject(json));}catch(Exception e){reply(callId,null,message(e));}});}}
 String message(Exception e){if(e instanceof SecurityException)return "访问被系统拒绝，请授予照片和视频权限";return e.getMessage()==null?"操作失败，请刷新后重试":e.getMessage();}
 void reply(int callId,Object result,String error){String encoded=result==null?"null":result instanceof String?JSONObject.quote((String)result):result.toString();runOnUiThread(()->web.evaluateJavascript("window.nativeResult("+callId+","+encoded+","+(error==null?"null":JSONObject.quote(error))+")",null));}
 boolean permission(String name){return checkSelfPermission(name)==PackageManager.PERMISSION_GRANTED;}
 boolean fullMediaRead(){return Build.VERSION.SDK_INT>=33?permission(Manifest.permission.READ_MEDIA_IMAGES)&&permission(Manifest.permission.READ_MEDIA_VIDEO):permission(Manifest.permission.READ_EXTERNAL_STORAGE);}
