 boolean silentFor(Uri media){boolean video=media.toString().contains("/video/");boolean fullType=Build.VERSION.SDK_INT>=33?permission(video?Manifest.permission.READ_MEDIA_VIDEO:Manifest.permission.READ_MEDIA_IMAGES):permission(Manifest.permission.READ_EXTERNAL_STORAGE);return Build.VERSION.SDK_INT>=31&&MediaStore.canManageMedia(this)&&permission(Manifest.permission.ACCESS_MEDIA_LOCATION)&&fullType;}
 ArrayList<Uri> visibleMediaUris(){ArrayList<Uri> visible=new ArrayList<>();for(boolean video:new boolean[]{false,true}){if(!canReadType(video))continue;Uri collection=video?MediaStore.Video.Media.EXTERNAL_CONTENT_URI:MediaStore.Images.Media.EXTERNAL_CONTENT_URI;try(Cursor c=getContentResolver().query(collection,new String[]{"_id"},"is_trashed=0 AND is_pending=0",null,null)){if(c!=null)while(c.moveToNext())visible.add(ContentUris.withAppendedId(collection,c.getLong(0)));}catch(SecurityException ignored){}}return visible;}
 JSONObject mediaAccess()throws JSONException {ArrayList<Uri> visible=visibleMediaUris();boolean imagesSilent=silentFor(MediaStore.Images.Media.EXTERNAL_CONTENT_URI),videosSilent=silentFor(MediaStore.Video.Media.EXTERNAL_CONTENT_URI);int writable=0;for(Uri media:visible)if((media.toString().contains("/video/")?videosSilent:imagesSilent)||hasWriteGrant(media))writable++;boolean full=fullMediaRead();return new JSONObject().put("supported",Build.VERSION.SDK_INT>=31).put("ready",!visible.isEmpty()&&writable==visible.size()).put("fullAccess",full).put("scope",full?"all":canReadType(false)||canReadType(true)?"partial":"none").put("visible",visible.size()).put("writable",writable).put("manager",Build.VERSION.SDK_INT>=31&&MediaStore.canManageMedia(this));}
