 void nextWriteBatch()throws Exception{if(writeRemaining.isEmpty()){JSONObject status=mediaAccess();if(writeUnverified>0)status.put("warning","有 "+writeUnverified+" 项授权未生效，请刷新后重试");reply(pendingId,status,null);return;}writeBatch=new ArrayList<>(writeRemaining.subList(0,Math.min(1000,writeRemaining.size())));PendingIntent request=MediaStore.createWriteRequest(getContentResolver(),writeBatch);runOnUiThread(()->{try{startIntentSenderForResult(request.getIntentSender(),106,null,0,0,0);}catch(Exception e){reply(pendingId,null,message(e));}});}
